  "Aktivdir": "Etkin",
  "İstifadəçinin ID-si sorğuya (userId) saytın imzaladığı tokendən əlavə olunur. Ünvanda {userId} yaza bilərsən. AI onu dəyişə bilməz.": "Kullanıcının ID'si, sitenin imzaladığı token'dan isteğe (userId) eklenir. Adreste {userId} yazabilirsin. AI bunu değiştiremez.",
  "Diqqət: bu əməliyyat daxil olmamış ziyarətçilərə də açıqdır. Yalnız zərərsiz əməliyyatlar üçün (bilet, müraciət, rezerv) istifadə et; sifariş ləğvi kimi hesaba aid işlər üçün yuxarıdakı qutunu işarələ.": "Dikkat: bu işlem giriş yapmamış ziyaretçilere de açıktır. Yalnızca zararsız işlemler için (bilet, başvuru, rezervasyon) kullan; sipariş iptali gibi hesaba ait işler için yukarıdaki kutuyu işaretle.",
