  "Müraciətiniz göndərildi.": "Başvurunuz gönderildi.",
  "Yadda saxlanıldı.": "Kaydedildi.",
  "Əməliyyatlar": "İşlemler",
  "Çat istifadəçinin istəyi ilə sənin saytında əməliyyat icra edə bilsin: sifarişi ləğv et, bilet yarat, görüş rezerv et, müraciət göndər. Hər əməliyyat yalnız istifadəçi kartı görüb təsdiq verəndən sonra icra olunur.": "Sohbet, kullanıcının isteğiyle sitende işlem yapabilsin: siparişi iptal et, talep oluştur, görüşme rezervasyonu yap, başvuru gönder. Her işlem yalnızca kullanıcı kartı görüp onayladıktan sonra gerçekleştirilir.",
  "Əməliyyatlar qoşulub": "İşlemler bağlı",
  "İmza açarı yaradılıb": "İmza anahtarı oluşturuldu",
  "İstifadəçi tokeni hazırdır": "Kullanıcı token'ı hazır",
  "Təhlükəsizlik necə işləyir": "Güvenlik nasıl çalışır",
  "AI heç vaxt əməliyyatı özü icra etmir. O yalnız təklif yaradır; istifadəçi nə olacağını (bütün dəyərlərlə) kartda görür və “Təsdiq et” düyməsinə basır. Təsdiq birdəfəliklədir və 10 dəqiqədən sonra bitir.": "AI işlemi asla kendisi gerçekleştirmez. Yalnızca öneri oluşturur; kullanıcı ne olacağını (tüm değerlerle) kartta görür ve “Onayla” düğmesine basar. Onay tek seferliktir ve 10 dakika sonra sona erer.",
  "Yalnız burada təyin etdiyin əməliyyatlar və parametrlər mümkündür. Hər parametr tip, uzunluq və icazəli dəyərlər üzrə yoxlanır, artıq sahələr atılır.": "Yalnızca burada tanımladığın işlemler ve parametreler mümkündür. Her parametre tür, uzunluk ve izin verilen değerlere göre denetlenir, fazla alanlar atılır.",
  "İstifadəçi ID-si yalnız saytın imzaladığı tokendən gəlir; AI və ya ziyarətçi başqasının adından əməliyyat edə bilməz. Təsdiqi də eyni istifadəçi verməlidir.": "Kullanıcı ID'si yalnızca sitenin imzaladığı token'dan gelir; AI veya ziyaretçi başkası adına işlem yapamaz. Onayı da aynı kullanıcı vermelidir.",
  "Sorğular imzalanır (HMAC), təkrar icra qarşısı üçün unikal açarla gedir və avtomatik təkrarlanmır. Cavab gəlməzsə nəticə “bəlli deyil” kimi bildirilir, uğur uydurulmur.": "İstekler imzalanır (HMAC), tekrar çalıştırmayı önlemek için benzersiz anahtarla gider ve otomatik tekrarlanmaz. Yanıt gelmezse sonuç “belli değil” olarak bildirilir, başarı uydurulmaz.",
  "İstifadəçi başına saatda 5 icra, sayt üzrə gündə 500 icra limiti var. Hər addım aşağıdakı jurnala yazılır.": "Kullanıcı başına saatte 5, site başına günde 500 işlem sınırı vardır. Her adım aşağıdaki günlüğe yazılır.",
  "Əməliyyatları icra edən daxili API. Yalnız yazma sorğuları (POST, PUT, PATCH, DELETE) göndərilir; oxuma üçün “Müştəri məlumatı” bölməsindən istifadə et.": "İşlemleri gerçekleştiren iç API. Yalnızca yazma istekleri (POST, PUT, PATCH, DELETE) gönderilir; okuma için “Müşteri verisi” bölümünü kullan.",
