  "Əvvəlcə sorğunun necə görünəcəyinə bax (heç nə göndərilmir). Sonra istəsən real sınaq sorğusu göndər: o X-Chatbot-Test: 1 başlığı ilə gedir, API-n bunu görüb əməliyyatı real icra etməməlidir.": "Önce isteğin nasıl görüneceğine bak (hiçbir şey gönderilmez). Sonra istersen gerçek bir deneme isteği gönder: X-Chatbot-Test: 1 başlığıyla gider, API'n bunu görüp işlemi gerçekten yapmamalıdır.",
