  "Hər sorğu X-Chatbot-Signature başlığı ilə gəlir. API-nda onu yoxla: yalnız bizdən gələn sorğuları qəbul et. X-Chatbot-Idempotency-Key təkrar gələrsə əməliyyatı bir də icra etmə.": "Her istek X-Chatbot-Signature başlığıyla gelir. API'nde onu doğrula: yalnızca bizden gelen istekleri kabul et. X-Chatbot-Idempotency-Key tekrar gelirse işlemi bir daha gerçekleştirme.",
