  "Söndürəndə köməkçi mesajlara cavab vermir, amma nömrə qoşulu qalır.": "Kapatınca asistan mesajlara yanıt vermez ama numara bağlı kalır.",
  "Mən yazanda köməkçi sussun": "Ben yazınca asistan sussun",
  "Telefondan müştəriyə özün cavab yazsan, köməkçi həmin söhbətdə 12 saat cavab verməz.": "Telefondan müşteriye kendin yanıt yazarsan, asistan o sohbette 12 saat yanıt vermez.",
  "Nömrə telefondakı “Əlaqəli cihazlar”dan çıxarılacaq və köməkçinin söhbət yaddaşı silinəcək. Telefonundakı WhatsApp mesajlarına toxunulmayacaq. Yenidən qoşmaq üçün QR lazım olacaq.": "Numara telefondaki “Bağlı cihazlar”dan kaldırılacak ve asistanın sohbet belleği silinecek. Telefonundaki WhatsApp mesajlarına dokunulmayacak. Yeniden bağlamak için QR gerekecek.",
  "Nömrəni ayır": "Numarayı ayır",
  "WhatsApp qoşulması üçün QR kod": "WhatsApp bağlantısı için QR kod",
  "Telefonda WhatsApp-ı aç: Ayarlar → Əlaqəli cihazlar.": "Telefonda WhatsApp'ı aç: Ayarlar → Bağlı cihazlar.",
  "“Cihaz qoş” düyməsinə bas və bu kodu WhatsApp-ın öz skanerində oxut (telefonun kamerası ilə yox).": "“Cihaz bağla” düğmesine bas ve bu kodu WhatsApp'ın kendi tarayıcısıyla okut (telefonun kamerasıyla değil).",
  "Kod bir neçə saniyədən bir yenilənir: skan etdikdən sonra bu səhifəni bağlama.": "Kod birkaç saniyede bir yenilenir: taradıktan sonra bu sayfayı kapatma.",
  "QR kod hazırlanır…": "QR kod hazırlanıyor…",
  "Bu, WhatsApp-ın rəsmi API-si deyil": "Bu, WhatsApp'ın resmi API'si değil",
  "QR ilə qoşulma qeyri-rəsmi üsuldur: WhatsApp bunu qaydalarına zidd saya və nömrəni müvəqqəti və ya həmişəlik blok edə bilər. Bu riski sən daşıyırsan. Əsas şəxsi nömrəni deyil, ayrıca bu iş üçün nömrəni qoş.": "QR ile bağlanmak resmi olmayan bir yöntemdir: WhatsApp bunu kurallarına aykırı sayabilir ve numarayı geçici veya kalıcı olarak engelleyebilir. Bu riski sen üstleniyorsun. Ana kişisel numaranı değil, bu iş için ayrı bir numara bağla.",
  "Riski başa düşürəm və nömrənin bloklana biləcəyi ilə razıyam.": "Riski anlıyorum ve numaranın engellenebileceğini kabul ediyorum.",
  "QR kodu göstər": "QR kodu göster",
  "Köməkçi yalnız şəxsi yazışmalarda cavab verir: qrup, status və kanallara yox.": "Asistan yalnızca özel yazışmalarda yanıt verir: gruplarda, durumlarda ve kanallarda vermez.",
  "Cavablar bloklanma riskini azaltmaq üçün bir az gecikmə ilə, saatda ən çox 150 cavab həddi ilə göndərilir.": "Yanıtlar engellenme riskini azaltmak için biraz gecikmeyle, saatte en fazla 150 yanıt sınırıyla gönderilir.",
  "Cavab tapılmayanda köməkçi telefon və ya e-poçt istəyir, müraciət “Müraciətlər” bölməsinə düşür və sənə e-poçt gəlir.": "Yanıt bulunamadığında asistan telefon veya e-posta ister, başvuru “Başvurular” bölümüne düşer ve sana e-posta gelir.",
  "Telefon hər gün internetdə olmalı deyil, amma 14 gündən çox oflayn qalsa və ya nömrəni “Əlaqəli cihazlar”dan çıxarsan, bağlantı kəsilir.": "Telefonun her gün internette olması gerekmez ama 14 günden fazla çevrimdışı kalırsa veya numarayı “Bağlı cihazlar”dan kaldırırsan bağlantı kesilir.",
  "Çox vaxt səbəb: artıq vergül, çatışmayan dırnaq və ya mötərizə.": "Çoğunlukla sebep: fazladan virgül, eksik tırnak veya parantez.",
