  "Dəstək botu": "Destek botu",
  "Şirkətin PDF, Word, sayt linki və ya FAQ-larından cavab verir. Operator əvəzi: uydurmur, bilmirsə operatora yönləndirir.": "Şirketin PDF, Word, site bağlantısı veya SSS'lerinden yanıt verir. Operatörün yerine geçer: uydurmaz, bilmiyorsa operatöre yönlendirir.",
  "Elan və məhsul məsləhətçisi": "İlan ve ürün danışmanı",
  "Saytındakı elanları, məhsulları və ya xidmətləri (maşın, daşınmaz əmlak, geyim, texnika və s.) axtarıb istifadəçiyə uyğununu təklif edir. Onları qaytaran API lazımdır.": "Sitendeki ilanları, ürünleri veya hizmetleri (araba, emlak, giyim, teknoloji vb.) arayıp kullanıcıya uygun olanı önerir. Bunları döndüren bir API gerekir.",
