  "Saytında hesabına daxil olmuş istifadəçi çatdan öz məlumatını (sifarişləri, ödənişləri, şikayətləri, sorğuları və s.) soruşa bilsin. Məlumat sorğu anında sənin API-ndən alınır və bizdə saxlanmır.": "Sitende hesabına giriş yapmış kullanıcı sohbetten kendi verilerini (siparişler, ödemeler, şikayetler, talepler vb.) sorabilsin. Veri, istek anında senin API'nden alınır ve bizde saklanmaz.",
