  "AI istifadəçi ID-sini özü seçə bilmir. Ziyarətçi çatda başqasının nömrəsini və ya ID-sini yazsa belə, yalnız tokendəki istifadəçinin məlumatı gətirilir.": "AI kullanıcı ID'sini kendisi seçemez. Ziyaretçi sohbette başkasının numarasını veya ID'sini yazsa bile yalnızca token'daki kullanıcının verisi getirilir.",
  "Kart nömrələri maskalanır, cavab mətni sorğu tarixçəsində saxlanmır, hər istifadəçi üçün sorğular məhdudlaşdırılıb.": "Kart numaraları maskelenir, yanıt metni sorgu geçmişinde saklanmaz, her kullanıcı için istekler sınırlandırılmıştır.",
  "Gizli açar və API açarın şifrələnmiş saxlanır, yalnız bir dəfə göstərilir.": "Gizli anahtar ve API anahtarın şifrelenerek saklanır, yalnızca bir kez gösterilir.",
  "İstifadəçinin məlumatını (sifariş, ödəniş, şikayət və s.) ID-si ilə qaytaran daxili API. Yalnız oxuma (GET) sorğuları göndərilir.": "Kullanıcının verisini (sipariş, ödeme, şikayet vb.) ID'siyle döndüren iç API. Yalnızca okuma (GET) istekleri gönderilir.",
