  "Botlardan qorunmaq üçün ziyarətçi başına dəqiqədə 10 mesaj həddi həmişə qalır, bunu real insan keçmir. Ziyarətçini tanımaq üçün brauzerdə təsadüfi anonim ID saxlanır (şəxsi məlumat deyil), saytının məxfilik siyasətində bunu qeyd etməyi məsləhət görürük.": "Botlardan korunmak için ziyaretçi başına dakikada 10 mesaj sınırı her zaman kalır, bunu gerçek bir insan aşmaz. Ziyaretçiyi tanımak için tarayıcıda rastgele anonim bir ID saklanır (kişisel veri değildir), sitenin gizlilik politikasında bunu belirtmeni öneririz.",
