  "Qaytarma, sifarişin ləğvi, rezerv kimi addım-addım proseslər üçün qayda yaz. Müştəri bu mövzuda yazanda bot addımlarla irəliləyir: lazım olan məlumatı soruşur və qaydanı pozmur. Tək cavab kifayətdirsə “Dəqiq cavablar”dan istifadə et.": "İade, sipariş iptali, rezervasyon gibi adım adım süreçler için kural yaz. Müşteri bu konuda yazdığında bot adımlarla ilerler: gerekli bilgiyi sorar ve kuralı çiğnemez. Tek yanıt yeterliyse “Kesin yanıtlar”ı kullan.",
