  "Vacib suallara özün cavab yaz. İstifadəçinin sualı yazdığın suallardan birinə uyğun gələndə bot cavabı olduğu kimi, süni intellektsiz və pulsuz verir. Uyğun gəlməyən suallara adi qaydada cavab verilir.": "Önemli sorulara kendin yanıt yaz. Kullanıcının sorusu yazdığın sorulardan birine uyduğunda bot yanıtı olduğu gibi, yapay zekasız ve ücretsiz verir. Uymayan sorulara olağan şekilde yanıt verilir.",
