  "Operatorla danışmaq istəyirəm": "Operatörle konuşmak istiyorum",
  "Operator söhbətə qoşuldu": "Operatör sohbete katıldı",
  "Salam! Sizə necə kömək edə bilərəm?": "Merhaba! Size nasıl yardımcı olabilirim?",
  "Əməliyyat ləğv olundu, heç nə dəyişmədi.": "İşlem iptal edildi, hiçbir şey değişmedi.",
  "Özün sına": "Kendin dene",
  "Çatda yaz, operatorun nə gördüyünü də gör": "Sohbete yaz, operatörün ne gördüğünü de gör",
  "Aşağıdakı suallardan birini bas. Solda ziyarətçinin gördüyü çatı, sağda isə eyni anda operatorun və sahibin panelində nə göründüyünü izləyirsən.": "Aşağıdaki sorulardan birine bas. Solda ziyaretçinin gördüğü sohbeti, sağda ise aynı anda operatörün ve sahibin panelinde neyin göründüğünü izlersin.",
  "Köməkçi": "Asistan",
