  "Açanda ziyarətçi çatda “Operatorla canlı yaz” düyməsini görür, Telegram və WhatsApp müştəriləri isə /operator yazır; sən buradan onlara real vaxtda cavab verirsən. Bu bölməyə baxa bildiyin vaxtlarda aç.": "Açtığında ziyaretçi sohbette “Operatörle canlı yaz” düğmesini görür, Telegram ve WhatsApp müşterileri ise /operator yazar; sen buradan onlara gerçek zamanlı yanıt verirsin. Bu bölüme bakabildiğin zamanlarda aç.",
