  "Saytında küncdəki çat düyməsində göstərilir. Yüklənməsə, standart çat ikonu çıxır.": "Sitendeki köşedeki sohbet düğmesinde gösterilir. Yüklenmezse standart sohbet simgesi görünür.",
  "Profil şəkli": "Profil resmi",
  "Çat açılanda başlıqda və botun hər mesajının yanında dairə içində göstərilir. Yüklənməsə, robot ikonu çıxır.": "Sohbet açıldığında başlıkta ve botun her mesajının yanında daire içinde gösterilir. Yüklenmezse robot simgesi görünür.",
  "Kvadrat və ya dairəvi şəkil yaxşı görünür. Şəkil avtomatik kiçildilir və “Saxla” düyməsi ilə saxlanır.": "Kare veya yuvarlak görseller iyi görünür. Görsel otomatik küçültülür ve “Kaydet” düğmesiyle kaydedilir.",
