  "Google Analytics hadisələri": "Google Analytics olayları",
  "Saytında Google Analytics (gtag) və ya Tag Manager varsa, çat bu hadisələri avtomatik göndərir. Heç nə quraşdırmaq lazım deyil: GA-da Hesabatlar → Hadisələr bölməsində görünəcək. Mesaj mətni və şəxsi məlumat göndərilmir.": "Sitende Google Analytics (gtag) veya Tag Manager varsa sohbet bu olayları otomatik gönderir. Kurulum gerekmez: GA'da Raporlar → Olaylar bölümünde görünür. Mesaj metni ve kişisel veri gönderilmez.",
  "Ziyarətçi çatı açdı": "Ziyaretçi sohbeti açtı",
  "AI-a sual yazdı": "Yapay zekaya soru sordu",
  "Çatdakı elana/məhsula keçdi (ad və qiymət ilə)": "Sohbetteki ilana/ürüne geçti (ad ve fiyatla)",
  "Əlaqə formasını doldurdu": "İletişim formunu doldurdu",
  "Operatorla canlı söhbət başladı": "Operatörle canlı sohbet başlattı",
  "Əməliyyatı təsdiqlədi (sifariş ləğvi, rezerv və s.)": "İşlemi onayladı (sipariş iptali, rezervasyon vb.)",
  "“ai_chat_lead” hadisəsini GA-da “Əsas hadisə” (konversiya) kimi işarələsən, çatın neçə müraciət gətirdiyini reklam hesabatlarında da görərsən.": "“ai_chat_lead” olayını GA'da “Temel etkinlik” (dönüşüm) olarak işaretlersen sohbetin kaç başvuru getirdiğini reklam raporlarında da görürsün.",
  "Başqa analitika (Yandex Metrica, Facebook Pixel) üçün saytında “caradvisor:event” hadisəsini dinlə. Söndürmək üçün koda data-analytics=\"off\" əlavə et.": "Diğer analitik araçlar (Yandex Metrica, Facebook Pixel) için sitende “caradvisor:event” olayını dinle. Kapatmak için koda data-analytics=\"off\" ekle.",
  "Şəkli tam ölçüdə aç": "Görseli tam boyutta aç",
  "Ziyarətçinin göndərdiyi şəkil": "Ziyaretçinin gönderdiği görsel",
  "Mesaj göndərildi. Ziyarətçi onu 15 saniyə ərzində görəcək.": "Mesaj gönderildi. Ziyaretçi 15 saniye içinde görecek.",
  "İndi saytda": "Şu an sitede",
  "AI ilə yazışır": "Yapay zekayla yazışıyor",
  "Ziyarətçiyə ilk mesaj": "Ziyaretçiye ilk mesaj",
  "məs. Salam! Bu elanla bağlı sualınız var?": "örn. Merhaba! Bu ilanla ilgili sorunuz var mı?",
  "İlk sən yaz": "İlk sen yaz",
  "Bir yolu seç. Nəticədə lazımsız filtr və sahələri silib “Yoxla”ya basmaq kifayətdir.": "Bir yol seç. Ardından gereksiz filtre ve alanları silip “Kontrol et”e basman yeterli.",
  "Telegram qrupu qoşuldu.": "Telegram grubu bağlandı.",
  "Bitrix24 qoşuldu.": "Bitrix24 bağlandı.",
  "Webhook qoşuldu. Sınaq göndərişi uğurlu oldu.": "Webhook bağlandı. Deneme gönderimi başarılı oldu.",
  "Sınaq çatdı.": "Deneme ulaştı.",
  "Müraciətləri ötür": "Başvuruları ilet",
  "Yeni müraciət (ad, əlaqə, sual) paneldən və e-poçtdan əlavə, burada seçdiyin yerə də dərhal göndərilsin. Heç bir rəsmi icazə lazım deyil.": "Her yeni başvuru (ad, iletişim, soru) panel ve e-postaya ek olarak buraya da hemen gönderilsin. Resmi onay gerekmez.",
  "Telegram qrupu": "Telegram grubu",
  "Qrup qoşulub": "Grup bağlı",
  "Satış komandanın Telegram qrupu varsa: düyməni bas, açılan pəncərədə qrupu seç. Bot qrupa əlavə olunur və müraciətləri ora yazır.": "Satış ekibinin Telegram grubu varsa: düğmeye bas, açılan pencerede grubu seç. Bot gruba eklenir ve başvuruları oraya yazar.",
  "Telegram-da qrupu seç…": "Telegram'da grubu seç…",
  "Qrupa qoş": "Gruba bağla",
  "Bitrix24 webhook linki": "Bitrix24 webhook bağlantısı",
  "Qoş": "Bağla",
  "Linki necə almaq olar?": "Bağlantıyı nasıl alırım?",
  "Bitrix24-də: Tətbiqlər → Developer resources → Other → Inbound webhook.": "Bitrix24'te: Uygulamalar → Developer resources → Other → Inbound webhook.",
  "İcazələrdə “CRM” seç və saxla.": "İzinlerde “CRM”yi seç ve kaydet.",
  "“Webhook to call REST API” linkini kopyalayıb bura yapışdır.": "“Webhook to call REST API” bağlantısını kopyalayıp buraya yapıştır.",
