  "Google Sheets-ə necə qoşmaq olar?": "Google Sheets'e nasıl bağlanır?",
  "Yeni Google Sheets cədvəli aç → Extensions (Genişləndirmələr) → Apps Script.": "Yeni bir Google Sheets tablosu aç → Uzantılar → Apps Script.",
  "Oradakı kodu silib aşağıdakını yapışdır və saxla.": "Oradaki kodu silip aşağıdakini yapıştır ve kaydet.",
  "Deploy → New deployment → növ: Web app. “Execute as: Me”, “Who has access: Anyone” seç → Deploy, icazə ver.": "Dağıt → Yeni dağıtım → tür: Web uygulaması. “Şu kullanıcı olarak yürüt: Ben”, “Erişimi olanlar: Herkes” seç → Dağıt, izin ver.",
  "Verilən “Web app URL” linkini bura yapışdır və “Qoş” bas.": "Verilen “Web uygulaması URL'si”ni buraya yapıştır ve “Bağla”ya bas.",
  "Kopyalandı.": "Kopyalandı.",
  "Make, Zapier və ya n8n istifadə edirsənsə, onların “Webhook” linkini də bura yazmaq olar: hər müraciət JSON kimi göndərilir (event, name, contact, question, page, conversation).": "Make, Zapier veya n8n kullanıyorsan onların “Webhook” bağlantısını da buraya yazabilirsin: her başvuru JSON olarak gönderilir (event, name, contact, question, page, conversation).",
  "Serverdə CHANNEL_SECRET_KEY təyin edilməyib: Bitrix24 və webhook linkləri şifrəli saxlanmadığı üçün qoşulmur.": "Sunucuda CHANNEL_SECRET_KEY tanımlı değil: Bitrix24 ve webhook bağlantıları şifreli saklanamadığı için bağlanamaz.",
  "Sınaq müraciəti göndər": "Deneme başvurusu gönder",
  "Saytın ünvanını yaz, məs. https://magaza.az (https olmalıdır).": "Sitenin adresini yaz, örn. https://magaza.com (https olmalı).",
  "Saytın WordPress + WooCommerce üzərindədirsə, API açarı və texniki iş lazım deyil: yalnız saytın ünvanını yaz. Məhsullar, qiymətlər, şəkillər və kateqoriyalar WooCommerce-in açıq vitrin API-sindən oxunur.": "Siten WordPress + WooCommerce üzerindeyse API anahtarı ve teknik iş gerekmez: yalnızca sitenin adresini yaz. Ürünler, fiyatlar, görseller ve kategoriler WooCommerce'in açık vitrin API'sinden okunur.",
  "Mağazanın ünvanı": "Mağaza adresi",
  "Konfiqurasiyanı hazırla": "Yapılandırmayı hazırla",
  "Hazırdır. Aşağıda “Yoxla” düyməsinə bas: mağazadan bir neçə məhsul gəlməlidir.": "Hazır. Aşağıda “Kontrol et”e bas: mağazadan birkaç ürün gelmeli.",
  "Qiymətlər 2 onluq rəqəmli valyuta üçün hazırlanıb (AZN, USD, EUR, TRY, RUB). Yoxlamada “məhsul gəlmədi” xətası çıxsa, saytda WooCommerce REST API bağlı ola bilər: hosting və ya təhlükəsizlik plaginində /wp-json yolunu aç.": "Fiyatlar 2 ondalık basamaklı para birimleri için ayarlandı (AZN, USD, EUR, TRY, RUB). Kontrolde “ürün gelmedi” hatası çıkarsa sitede WooCommerce REST API kapalı olabilir: hosting veya güvenlik eklentisinde /wp-json yolunu aç.",
