  "Kod qəbul olundu.": "Kod kabul edildi.",
  "Promo kodun var?": "Promosyon kodun var mı?",
  "Çatın rejimi “Elanlar + dəstək” oldu: elan axtarışı və bilik bazası birlikdə işləyir. Bilik bazası bölməsindən dəyişə bilərsən.": "Sohbet modu artık “İlanlar + destek”: ilan araması ve bilgi bankası birlikte çalışır. Bilgi bankası bölümünden değiştirebilirsin.",
  "Çat hazırda “Yalnız dəstək” rejimindədir və elan axtarmır. Mənbəni yadda saxlasan, rejim avtomatik “Elanlar + dəstək” olacaq: bilik bazası da işləməyə davam edəcək.": "Sohbet şu anda “Yalnız destek” modunda ve ilan aramıyor. Kaynağı kaydedersen mod otomatik olarak “İlanlar + destek” olur: bilgi bankası da çalışmaya devam eder.",
  "API ayarları silinəcək, çat şəxsi məlumatı göstərməyəcək. Gizli açar yalnız daxil olmuş istifadəçi üçün əməliyyat yoxdursa silinir.": "API ayarları silinecek, sohbet kişisel verileri göstermeyecek. Gizli anahtar yalnızca giriş yapmış kullanıcılar için işlem yoksa silinir.",
  "Gizli açar: istifadəçini tanımaq üçün": "Gizli anahtar: kullanıcıyı tanımak için",
  "Saytın serveri bu açarla “bu istifadəçi Aysel-dir” deyən imzalı token yaradır. Bir açar həm müştəri məlumatı, həm də daxil olmuş istifadəçinin əməliyyatları üçündür.": "Sitenin sunucusu bu anahtarla “bu kullanıcı Aysel” diyen imzalı bir token oluşturur. Tek anahtar hem müşteri verileri hem de giriş yapmış kullanıcının işlemleri içindir.",
  "Saytında token ver": "Sitende token ver",
  "Bu kodu saytının proqramçısı öz serverinə qoyur: istifadəçi daxil olanda token yaradır və səhifəyə verir. Gizli açarı heç vaxt brauzerə vermə.": "Bu kodu sitenin geliştiricisi kendi sunucusuna koyar: kullanıcı giriş yaptığında token oluşturur ve sayfaya verir. Gizli anahtarı asla tarayıcıya verme.",
  "response.fields.{k} tanınmır, sahə adı ingiliscə olmalıdır: “{h}”.": "response.fields.{k} tanınmıyor, alan adı İngilizce olmalı: “{h}”.",
  "response.fields.{k} tanınmır və atılacaq. Standart adlardan birini yaz ({list}) və ya bu sahəni “attributes” içinə köçür.": "response.fields.{k} tanınmıyor ve atılacak. Standart adlardan birini yaz ({list}) veya bu alanı “attributes” içine taşı.",
  "Canlı operator açıqdır, amma indi işçi saatlarından kənardır: müştəriyə operatorların işləmədiyi deyilir və əlaqə qoymaq təklif olunur.": "Canlı operatör açık, ancak şu an mesai dışı: müşteriye operatörlerin çalışmadığı söylenir ve iletişim bırakması önerilir.",
  "Canlı operator açıqdır: müştəri /operator yazsa söhbət Müraciətlər bölməsinə düşür və sən buradan cavab verirsən.": "Canlı operatör açık: müşteri /operator yazarsa sohbet Talepler bölümüne düşer ve oradan cevap verirsin.",
  "Canlı operator bağlıdır: işçi saatları yadda qalır, amma operator açılana qədər təsir etmir.": "Canlı operatör kapalı: mesai saatleri saklanır ancak operatör açılana kadar etkisi yoktur.",
  "Canlı operator hazırda bağlıdır: müştəri /operator yazsa, bot cavab verməyə davam edir.": "Canlı operatör şu anda kapalı: müşteri /operator yazarsa bot cevap vermeye devam eder.",
  "Gecə növbəsi üçün bitişi başlanğıcdan kiçik yaz (məs. 22:00–02:00, ertəsi gün bitir). 00:00–00:00 bütün gün deməkdir.": "Gece vardiyası için bitişi başlangıçtan önce yaz (ör. 22:00–02:00, ertesi gün biter). 00:00–00:00 tüm gün demektir.",
  "Saatları dəyiş": "Saatleri değiştir",
  "Telegram və WhatsApp-da müştəri /operator yazaraq (və ya “operatorla danışmaq istəyirəm” kimi) insanla yazışmaya keçə bilər.": "Telegram ve WhatsApp'ta müşteri /operator yazarak (veya “operatörle konuşmak istiyorum” gibi) bir insanla yazışmaya geçebilir.",
  "İndi işçi saatlarından kənardır: ziyarətçilərə “Operatorla canlı yaz” düyməsi göstərilmir, onlara əlaqə forması təklif olunur. Açıq söhbətlərə cavab verə bilərsən.": "Şu an mesai dışı: ziyaretçiler “Operatörle canlı yaz” düğmesini görmez, onlara iletişim formu önerilir. Açık sohbetlere cevap verebilirsin.",
