  "Öz bacarıqların": "Özel beceriler",
  "Köməkçi saytında iş görsün: sifarişin statusu, ləğv, ünvan dəyişikliyi və s. Müştəri hər addımı təsdiqləyir.": "Asistan sitende iş yapsın: sipariş durumu, iptal, adres değişikliği vb. Müşteri her adımı onaylar.",
  "“Müştəri geri qaytarma istəyəndə əvvəl sifariş nömrəsini soruş, sonra…” kimi: nə vaxt nə etsin, sən yaz.": "“Müşteri iade isterse önce sipariş numarasını sor, sonra…” gibi: ne zaman ne yapacağını sen yaz.",
