  "Sənin məlumatından başqa, sahənlə bağlı ümumi suallara da cavab versin (“ümumi məlumatdır” qeydi ilə).": "Senin verilerinin yanında alanınla ilgili genel sorulara da yanıt versin (“genel bilgidir” notuyla).",
  "Ziyarətçi şəkil göndərəndə köməkçi oxşar elan, məhsul və ya məlumat axtarsın. Hər şəkil ayrıca sorğu sayılır.": "Ziyaretçi fotoğraf gönderince asistan benzer ilan, ürün veya bilgi arasın. Her fotoğraf ayrı bir sorgu sayılır.",
  "Ziyarətçi yazmamış, şərtə görə çat düyməsinin yanında salam kartı göstərilsin.": "Ziyaretçi yazmadan, koşullara göre sohbet butonunun yanında karşılama kartı gösterilsin.",
