  "“WPCode” (və ya “Insert Headers and Footers”) plaginini qur → Code Snippets → Footer bölməsinə yapışdır → Saxla. Plaginsiz: Görünüş → Tema redaktoru → footer.php, </body>-dən əvvəl.": "“WPCode” (veya “Insert Headers and Footers”) eklentisini kur → Code Snippets → Footer'a yapıştır → Kaydet. Eklentisiz: Görünüm → Tema düzenleyici → footer.php, </body>'den önce.",
