  "Hər sətirdə bir nömrə və ya ad yaz. Nömrəni istənilən formada yazmaq olar (050 123 45 67 və ya +994501234567). Ad yazsan, adamın WhatsApp-da özünə qoyduğu adla müqayisə olunur, sənin telefonda yadda saxladığın adla yox. Bu adamlar yazanda köməkçi susur, cavabı sən özün verirsən.": "Her satıra bir numara veya ad yaz. Numara herhangi bir biçimde yazılabilir (050 123 45 67 veya +994501234567). Ad, kişinin WhatsApp'ta kendine koyduğu adla karşılaştırılır, senin telefonda kaydettiğin adla değil. Bu kişiler yazdığında asistan sessiz kalır, cevabı sen verirsin.",
