  "Qoşulan nömrəyə yazan hər kəsə cavab veriləcək (yuxarıdakı siyahıdakılardan başqa). Ona görə ayrıca iş nömrəsi məsləhətdir.": "Bağlı numaraya yazan herkese cevap verilir (yukarıdaki listedekiler hariç). Bu yüzden ayrı bir iş numarası önerilir.",
  "Yazılı və səsli mesajlara, həmçinin şəkillərə cavab verir (səs mətnə çevrilir, şəkli köməkçi özü anlayır).": "Yazılı ve sesli mesajlara, ayrıca fotoğraflara cevap verir (ses metne çevrilir, fotoğrafı asistan kendisi anlar).",
