  "Qalan günlər üçün yalnız fərqi ödəyirsən. Yeni limit və imkanlar dərhal açılır, dövrün bitmə tarixi dəyişmir.": "Kalan günler için yalnızca farkı ödersin. Yeni limit ve özellikler hemen açılır, dönemin bitiş tarihi değişmez.",
