  "Planlar yadda saxlandı.": "Planlar kaydedildi.",
  "Qiymət, cavab limiti və imkanlar. Yeni sifarişlərə dərhal tətbiq olunur; mövcud abunələrdə imkanlar dərhal, limit isə növbəti yeniləmədə dəyişir.": "Fiyat, yanıt limiti ve özellikler. Yeni siparişlere hemen uygulanır; mevcut aboneliklerde özellikler hemen, limit ise sonraki yenilemede değişir.",
