  "Planlar dəyişsin?": "Planlar değişsin mi?",
  "İmkanlar bütün mövcud abunəçilər üçün dərhal dəyişir. Aktiv abunəçisi olan planı silmək və ya kodunu dəyişmək olmaz: əvvəlcə həmin müştəriləri başqa plana keçir.": "Özellikler tüm mevcut aboneler için hemen değişir. Aktif abonesi olan plan silinemez veya kodu değiştirilemez: önce bu müşterileri başka bir plana geçir.",
  "Plan verildi.": "Plan verildi.",
  "Plan götürüldü.": "Plan kaldırıldı.",
  "Ödənişsiz plan vermək (sınaq uzatma, kompensasiya). Ödənişli sifarişlər “Ödənişlər”dən təsdiqlənir.": "Ödemesiz plan ver (deneme uzatma, telafi). Ücretli siparişler “Ödemeler”den onaylanır.",
