  "Limit dolanda planı yüksəlt və ya əlavə paket al: +{n} cavab {a} ₼.": "Limit dolunca planı yükselt veya ek paket al: +{n} yanıt {a} ₼.",
  "Limit dolanda planı yüksəldə bilərsən.": "Limit dolunca planı yükseltebilirsin.",
  "Limitin 80%-i və hamısı işlənəndə e-poçt gəlir. Gözlənilməz borc yoxdur: limit dolanda çat əlaqə formasına keçir.": "Limitin %80'i ve tamamı kullanılınca e-posta gelir. Sürpriz borç yok: limit dolunca sohbet iletişim formuna geçer.",
  "Xeyr. Planın qiyməti sabitdir, əlavə fatura gəlmir. Aylıq cavab limitinin 80%-i və hamısı işlənəndə e-poçt gəlir. Limit dolanda köməkçi dayanır və ziyarətçiyə əlaqə forması çıxır: istəsən planı yüksəldir və ya əlavə paket alırsan.": "Hayır. Plan fiyatı sabittir, ek fatura gelmez. Aylık yanıt limitinin %80'i ve tamamı kullanılınca e-posta gelir. Limit dolunca asistan durur ve ziyaretçiye iletişim formu çıkar: istersen planı yükseltir veya ek paket alırsın.",
  "Plan avtomatik yenilənirmi? Necə ləğv edim?": "Plan otomatik yenilenir mi? Nasıl iptal ederim?",
  "Hazırda plan avtomatik uzanmır: dövr bitməyə 3 gün qalmış e-poçtla xatırladırıq, yeniləməsən dövrün sonunda dayanır. Ödənilmiş dövr geri qaytarılmır. Ucuz plana keçid növbəti dövrdən olur, bahalı plana keçəndə isə yalnız qalan günlərin fərqini ödəyirsən.": "Şu an plan otomatik yenilenmiyor: dönem bitmeden 3 gün önce e-postayla hatırlatırız, yenilemezsen dönem sonunda durur. Ödenmiş dönem iade edilmez. Ucuz plana geçiş sonraki dönemden olur, pahalı plana geçerken yalnızca kalan günlerin farkını ödersin.",
  "Komandanı dəvət et: operatorlar email ilə qoşulur və yalnız canlı söhbət qutusunu görür, ayarlara və ödənişə toxuna bilmir.": "Ekibini davet et: operatörler e-postayla katılır ve yalnızca canlı sohbet kutusunu görür, ayarlara ve ödemeye dokunamaz.",
  "Hazır cavabları bir dəfə yaz, operatorlar bir kliklə seçir. AI qaralaması planın limitinə yazılmır.": "Hazır yanıtları bir kez yaz, operatörler tek tıkla seçer. AI taslakları plan limitine sayılmaz.",
