  "cavab qalıb": "yanıt kaldı",
  "Pulsuz başla: kart lazım deyil, 100 pulsuz cavabla sına. Emailinə təsdiq kodu göndəriləcək.": "Ücretsiz başla: kart gerekmez, 100 ücretsiz yanıtla dene. E-postana doğrulama kodu gönderilecek.",
  "pulsuz sınaq cavabı": "ücretsiz deneme yanıtı",
  "Qeydiyyatda 100 pulsuz cavab (14 gün): bütün imkanları real ziyarətçilərlə yoxla, kart tələb olunmur.": "Kayıtta 100 ücretsiz yanıt (14 gün): tüm özellikleri gerçek ziyaretçilerle dene, kart gerekmez.",
  "Kart tələb olunmur · 100 pulsuz cavab": "Kart gerekmez · 100 ücretsiz yanıt",
  "Gələn sayt ilk planını alanda +{n} bonus cavab alır.": "Gelen site ilk planını aldığında +{n} bonus yanıt alır.",
  "Komissiya müştərinin hər plan və paket ödənişindən hesablanır: bonus və pulsuz sınaq sayılmır.": "Komisyon müşterinin her plan ve paket ödemesinden hesaplanır: bonus ve ücretsiz deneme sayılmaz.",
  "Partnyorun kodu ilə gələn saytların plan ödənişlərindən komissiya yazılır. Ödənişi özün edib balansdan çıxırsan.": "Partner koduyla gelen sitelerin plan ödemelerinden komisyon yazılır. Ödemeyi kendin yapıp bakiyeden düşersin.",
  "Komissiya müştərinin hər plan və paket ödənişindən faizlə hesablanır. Bonus, hədiyyə və pulsuz sınaq sayılmır.": "Komisyon, müşterinin her plan ve paket ödemesinin yüzdesidir. Bonus, hediye ve ücretsiz deneme sayılmaz.",
  "Yeni müştəri bonusu (cavab)": "Yeni müşteri bonusu (yanıt)",
  "Kodla gələn müştəri ilk planını alanda bir dəfə bu qədər əlavə cavab alır (0 = bonus yoxdur). Müddət dəyişəndə artıq bağlı müştərilərə də tətbiq olunur.": "Kodla gelen müşteri ilk planını aldığında bir kez bu kadar ek yanıt alır (0 = bonus yok). Süre değişikliği zaten bağlı müşterilere de uygulanır.",
  "Kod qəbul olundu: ilk planını alanda +{n} bonus cavab.": "Kod kabul edildi: ilk planında +{n} bonus yanıt.",
  "Rayon, küçə, ev": "İlçe, sokak, ev",
  "Seçim": "Seçim",
  "Sifariş qəbulu": "Sipariş alımı",
  "Saytınızın API-si lazım deyil. AI müştəridən bu məlumatları söhbətdə bir-bir soruşur, xülasəni göstərib təsdiq alır və sifarişi Müraciətlərə göndərir. Siz e-poçtla (və qoşulubsa Telegram qrupu və ya Bitrix24 ilə) dərhal xəbər alırsınız.": "Sitenizin API'sine gerek yok. AI bu bilgileri sohbette müşteriye tek tek sorar, özeti gösterip onay alır ve siparişi Taleplere gönderir. E-postayla (bağlıysa Telegram grubu veya Bitrix24 ile de) hemen haberdar olursunuz.",
