  "WhatsApp, Telegram və ya hesabsız alış edən müştəri sifariş nömrəsini və sifarişdə yazdığı telefonu deyir.": "WhatsApp, Telegram'dan yazan veya hesapsız alışveriş yapan müşteri sipariş numarasını ve siparişte yazdığı telefonu söyler.",
  "Bot sifarişi sənin API-ndən gətirir və telefonun son 9 rəqəmi uyğun gələrsə statusu göstərir. Uyğun gəlməsə “tapılmadı” deyilir: sifarişin olub-olmadığı bildirilmir.": "Bot siparişi API'nizden alır ve telefonun son 9 hanesi eşleşirse durumu gösterir. Eşleşmezse “bulunamadı” der: siparişin var olup olmadığını açıklamaz.",
  "Təxminə qarşı: eyni sifarişə saatda 5 uğursuz cəhd, bir söhbətdə 10 dəqiqədə 5 axtarış. Telefon və e-poçt cavabda maskalanır.": "Tahmine karşı: aynı siparişe saatte 5 başarısız deneme, bir sohbette 10 dakikada 5 sorgu. Telefon ve e-posta yanıtta maskelenir.",
