  "Müştəri operator istəyəndə AI həmişə ötürür. Aşağıdakı hallarda isə özü qərar verir. Operator işləyirsə söhbət canlı qutuya səbəb etiketi ilə düşür, işləmirsə bot “operator sizə yazacaq” deyir, əlaqəni alır və müraciət yaradır.": "Müşteri operatör istediğinde AI her zaman aktarır. Aşağıdaki durumlarda ise kendisi karar verir. Operatör çalışıyorsa sohbet neden etiketiyle canlı sohbete düşer; çalışmıyorsa bot “operatör size yazacak” der, iletişim bilgisini alır ve talep oluşturur.",
  "😠 Müştəri narazı və ya əsəbidirsə": "😠 Müşteri memnun değil veya sinirliyse",
