  "Canlı söhbətdə qoşulanda müştəri “{name} söhbətə qoşuldu” yazısını, adını və şəklini görür. AI cavab verəndə isə “AI köməkçi” nişanı göstərilir.": "Canlı sohbete katıldığınızda müşteri “{name} sohbete katıldı” yazısını, adınızı ve fotoğrafınızı görür. AI yanıt verirken “AI asistan” rozeti gösterilir.",
