  "Bütün planlarda: bilik bazası, sifariş və randevu qəbulu, ağıllı operator çağırışı, AI qaralama rejimi və müştəriyə xatırlatmalar.": "Tüm planlarda: bilgi bankası, sipariş ve randevu alma, akıllı operatöre aktarma, AI taslak modu ve müşteri hatırlatmaları.",
  "Vaxtım yoxdur. Qurulumu siz edə bilərsiniz?": "Vaktim yok. Kurulumu siz yapabilir misiniz?",
  "Bəli, pulsuz. Qeydiyyatdan sonra paneldə “Qurulumu bizə həvalə et” bas və biznesin, məhsul və qiymətlərin haqqında yaz: köməkçini komandamız öyrədib qurur, sən yalnız yoxlayırsan.": "Evet, ücretsiz. Kayıttan sonra panelde “Kurulumu bize bırak” düğmesine tıklayın ve işletmeniz, ürünleriniz ve fiyatlarınız hakkında yazın: asistanı ekibimiz eğitip kurar, siz sadece kontrol edersiniz.",
