  "Narazı və ya almağa hazır müştərini AI özü səbəbi ilə operatora ötürür. Operator Telegram-dan da cavab yaza bilir.": "Memnun olmayan veya satın almaya hazır müşteriyi AI nedeniyle birlikte operatöre aktarır. Operatör Telegram'dan da yanıt verebilir.",
  "AI-a hələ güvənmirsənsə qaralama rejimi: AI cavabı hazırlayır, operator bir kliklə göndərir.": "AI'ya henüz güvenmiyor musunuz? Taslak modu: AI yanıtı hazırlar, operatör tek tıkla gönderir.",
  "Sifariş və randevu": "Sipariş ve randevu",
  "Sifarişi və randevunu çatda qəbul edir, API lazım deyil": "Sohbette sipariş ve randevu alır, API gerekmez",
  "Sahələri və ya xidmətlərlə iş saatlarını paneldə yazırsan. AI məlumatı söhbətdə toplayır, təsdiq alır və sənə göndərir. Randevuda yalnız boş vaxtları təklif edir.": "Panelde alanları veya hizmetleri ve çalışma saatlerini yazarsınız. AI bilgileri sohbette toplar, onay alır ve size gönderir. Randevuda yalnızca boş saatleri önerir.",
  "Sifarişlər lövhədə: mərhələ dəyişəndə müştəri Telegram, WhatsApp və ya e-poçtla avtomatik xəbər alır.": "Siparişler panoda: aşama değişince müşteri Telegram, WhatsApp veya e-postayla otomatik bilgilendirilir.",
