  "Müştəri sifariş nömrəsi və telefonu ilə girişsiz status soruşa bilər.": "Müşteri sipariş numarası ve telefonuyla giriş yapmadan durum sorabilir.",
  "Müştəri cavabdan sonra susubsa, istəsən ona bir dəfə nəzakətli xatırlatma gedir.": "Müşteri yanıttan sonra sessiz kalırsa, isterseniz ona bir kez nazik bir hatırlatma gider.",
  "Canlı operator və komanda, sifariş və randevu qəbulu, müştərinin öz məlumatı, saytında icra olunan əməliyyatlar, proaktiv mesajlar, səsli mesajla birlikdə Telegram və WhatsApp, statistika. Aşağıda hər birinin ziyarətçiyə və sənə necə göründüyünü görə bilərsən.": "Canlı operatör ve ekip, sipariş ve randevu alma, müşterinin kendi verisi, sitenizde yapılan işlemler, proaktif mesajlar, sesli mesajlarla Telegram ve WhatsApp, istatistikler. Aşağıda her birinin ziyaretçiye ve size nasıl göründüğünü görebilirsiniz.",
