  "Qaralama yalnız sahəyə yazılır, sən oxuyub göndərirsən. Plan limitinə sayılmır.": "Taslak yalnızca alana yazılır, sen okuyup gönderirsin. Plan limitine sayılmaz.",
  "Hər cavab saytdakı çat kimi plan limitindən 1 cavab sayılır. Günlük limit “Saytına qoş” səhifəsindəki ziyarətçi limitidir.": "Her yanıt, sitedeki sohbet gibi plandan 1 yanıt sayılır. Günlük limit, “Sitene ekle” sayfasındaki ziyaretçi limitidir.",
