  "Əlavə etdiyin saytlar seçdiyin vaxtda özü yenidən oxunur. Məzmun dəyişməyibsə heç nə edilmir.": "Eklediğin siteler seçtiğin zamanda otomatik olarak yeniden okunur. İçerik değişmediyse hiçbir şey yapılmaz.",
  "Saytındakı istifadəçi kimi yaz və məsləhətçinin cavabına bax. Hər cavab plan limitindən 1 cavab kimi sayılır.": "Sitendeki bir kullanıcı gibi yaz ve danışmanın yanıtını gör. Her yanıt plandan 1 yanıt sayılır.",
