  "Lazım olsa": "Gerekirse",
  "Hesabın, elan mənbəyi qoşulması, API açarı və çat vidjeti həmişəlik silinir. Geri qaytarmaq mümkün deyil. Ödənilmiş plan dövrü geri qaytarılmır.": "Hesabın, ilan kaynağı bağlantısı, API anahtarı ve sohbet widget'ı kalıcı olarak silinir. Geri alınamaz. Ödenmiş plan dönemi iade edilmez.",
  "Burada köməkçini ziyarətçi kimi yoxla. Dəyişikliyi saxlayandan sonra növbəti cavab yeni ayarla gəlir. Hər cavab plan limitindən 1 cavab sayılır.": "Asistanı burada ziyaretçi gibi dene. Değişikliği kaydettikten sonra bir sonraki yanıt yeni ayarlarla gelir. Her yanıt plandan 1 yanıt sayılır.",
  "Ziyarətçi yazmamış, şərtə uyğun gələndə çat düyməsinin yanında kart çıxır. Mətn sənindir, plan limitinə sayılmır. Söndürsən, heç bir kampaniya göstərilmir.": "Ziyaretçi yazmadan, koşul eşleştiğinde sohbet düğmesinin yanında bir kart çıkar. Metin senin, plan limitine sayılmaz. Kapatırsan hiçbir kampanya gösterilmez.",
  "Niyyət, əhval, etirazlar və növbəti addım. Plan limitinə sayılmır.": "Niyet, ruh hali, itirazlar ve sonraki adım. Plan limitine sayılmaz.",
